import { ChangeDetectorRef, EventEmitter, Output } from "@angular/core";
import { BroadcastingService } from "../../../../core/services/broadcasting/broadcasting.service";
import { broadCastBody } from "../../../../core/interfaces/login.interface";
import { Subscription } from "rxjs";

export class dragDropComponent {
  onItemDropped = new EventEmitter<string>();


  isDragging: boolean = false;
  dragBundleId: string = null;
  dragItemObj: { x: number, y: number } = { x: 0, y: 0 };

  yMargin: number = 10;
  constructor(protected cdr: ChangeDetectorRef, protected broadCastService: BroadcastingService) {


  }




  onMouseDown(e) {
    // console.log('MOSE DONW')
    // return;
    this.isDragging = false;
    this.dragBundleId = null;
    try {
      const cdragBundle = e.target?.closest('.alpha-drag-handler')?.id ;
      if (cdragBundle) {
        this.isDragging = true;
        this.dragBundleId = cdragBundle;
        this.dragItemObj = {
          x: e.clientX,
          y: e.clientY
        };
      }
    } catch (error) {

    }
    this.cdr.detectChanges();
  }
  onMouseMove(e) {
    // return;
    if (!this.isDragging) return;
    this.dragItemObj = {
      x: e.clientX,
      y: e.clientY
    };
  }
  onMouseUp(e) {
    if (e.target?.closest('#alpha-drop-zone')?.id == 'alpha-drop-zone' && this.dragBundleId) {
      this.addDocument(this.dragBundleId)
    }
    this.isDragging = false;
    this.dragBundleId = null;
    this.dragItemObj = { x: 0, y: 0 };
    this.cdr.detectChanges();
  }




  async addDocument(nBundledetailid: string) {
    if (!nBundledetailid) return;

    // const data = await this.individualService.getTabinfo([nBundledetailid])
    this.onItemDropped.emit(nBundledetailid);
    // this.handleItemDrop(data);
  }
  protected async handleItemDrop(data: any) {
  }


  protected getCaseId() {
  }
}