  @HostListener('window:message', ['$event'])
  onPdf = async (event: MessageEvent) => {
    try {
      if (event.origin !== window.location.origin || !event.data.identity) {
        return;
      }
      try {
        if (event.data.message.event == 'LINK-EXPLORER-CHANGEDOC') {
          this.changeLinkExplorerDoc(event.data.message.data);
          return;
        } else if (event.data.message.event == 'LINK-EXPLORER-TYPE') {
          this.sendMessageToIframe(this.linkExp_left.nBundledetailid, event.data.message);
          this.sendMessageToIframe(this.linkExp_right.nBundledetailid, event.data.message, 2);
          return;
        }
      } catch (error) {
      }

      if (event.data.message && event.data.message.event && event.data.message.event == 'OPEN-ATTACHMENT') {
        let data = event.data.message;
        await this.openAttachmentsInNewTab(data?.data);
      }

      const index: number = this.documentList.findIndex(a => a.nBundledetailid == event.data.identity);
      if (index == -1) {
        const data: toolEvents = event.data.message;
        if (data.event == 'COMPARE-DATA-UPDATE' && this.compareMode && this.selectedTab.nBundledetailid == event.data.identity) {
          const index: number = this.compareDocumentList.findIndex(a => a.nBundledetailid == event.data.identity);
          if (data?.data?.currentPage == 1) {
            data.data.currentPage = this.compareDocumentList[index].onPage || 1;
          }
          this.compareDocumentList[index].currentPage = data.data.currentPage || 1;
          this.updateCompareData(this.compareDocumentList[index], data.data);

        }
        return
      };
      let x: DocumentTab = this.documentList[index];
      if (x) {
        const data: toolEvents = event.data.message;
        try {
          if (data?.data?.nPresentid) {
            this.handlePresentEvents(x, data);
            return;
          }
        } catch (error) {

        }
        if (data.event == 'CHANGE_DOC') {
          this.changeDoc(data.data, x, index);
        } else if (data.event == 'SWAP') {
          this.openFileViewer('SWAP', { nBundledetailid: event.data.identity });
        } else if (data.event == 'BIG-FACT') {
          if (data.data.nFSid) {
            // x.nFSid = data.data.nFSid;
            this.selectedFSid = data.data.nFSid;
            this.cdr.detectChanges();
          }
        } else if (data.event == 'REFRESH-BIGFACT') {
          this.changingValue.next(data);
        } else if (data.event == 'LINK_EXPLORER') {
          const file = { ...x };
          const Ofile = { ...x };
          file["cPath"] = this.senitizeUrl(x, null, null, 'I', this.linkMode);
          this.linkExp_left = file;
          Ofile["cPath"] = this.senitizeUrl(x, null, null, 'O', this.linkMode);
          this.linkExp_right = Ofile;
          this.linkexplorerMode = true;
          this.cdr.detectChanges();
        } else if (data.event == 'OPEN-HYPERLINK-FILE') {
          // this.openNewFile(data.data);
          // this.openHyperLinkFile(data.data);
          var isIndex: boolean = this.selectedTab?.originalPath.includes('index');
          if (isIndex) {
            if (this.nPresentid && this.presentDetail?.isHost) {
              const jBd = [data.data.nBundledetailid];
              this.presentSerice.presentMangeDocs(jBd, 'N', this.nPresentid);
            }
            this.cf.openHyperLinkFile(data.data.nBundledetailid, this.nCaseid, this.nPresentid);
          }
          else
            this.openNewFile(data.data);
        } else if (data.event == 'ON-CONVERT-TO-PAGE-LEVEL') {
          this.selectedFSid = data.data.nFSid;
          this.changingValue.next(data);
          this.cdr.detectChanges();
          // this.sendMessageToIframe(x.nBundledetailid, data.data);
        } else if (data.event == 'QFACT-COMPARE-POPUP-OPEN') {
          this.openCompareQFactPopup(x, data.data);
        } else if (data.event == 'QFACT-COMPARE-POPUP-SAVE-RESULT') {
          this.resolveCompareQFactPopupSave(data.data);
        } else if (data.event == 'COMPARE_MODE') {
          this.changeCompareMode(x, data.data);
          this.isDocViewCompare = false;
        } else if (data.event == 'OPEN-COMPARE-MODE') {
          this.isDocViewCompare = true;
          console.log('open compare mode', data);
          this.changeCompareModViaMarkNav(x, data.data);
        } else if (data.event == 'COMPARE-DATA-UPDATE') {
          this.documentList[index].currentPage = data.data.currentPage;
          this.updateCompareData(x, data.data);
        } else if (data.event == 'ZOOM') {
          this.toolBarOptions.zoom = data.data.zoom;
        } else if (data.event == 'CURRENT-PAGE') {
          this.documentList[index].currentPage = data.data.currentPage;
          if (data.data?.cTab && this.documentList[index].cTab !== data.data.cTab) {
            this.documentList[index].cTab = data.data.cTab;
            this.cdr.detectChanges();
          }
          this.toolBarOptions.currentPage = data.data.currentPage;
        } else if (data.event == 'DOC-INFO-LOADED') {
          if (data.data?.cTab && this.documentList[index].cTab !== data.data.cTab) {
            this.documentList[index].cTab = data.data.cTab;
            this.cdr.detectChanges();
          }
        } else if (data.event == 'FULL_SCREEN_CHANGE') {
          this.isFullScreen = data.data;
          this.cdr.detectChanges();
        } else if (data.event == 'OPEN-FACTSHEET') {
          this.handleFactSheetOpen(data.data);
        } else if (data.event == PdfEvents.CALLOUT_CAPTURE) {
          this.onCalloutCapture(data.data);
        } else if (data.event == PdfEvents.CALLOUT_DISMISS) {
          // Sent from pdf.component.exitCalloutMode (shortcut switch,
          // Escape, etc.) — tear down the popup overlay so the two
          // independent state holders stay aligned.
          this.dismissCallout();
        } else if (data.event == 'FILTER-ANNOTATION') {
          this.sendMessageToIframe(x.nBundledetailid, data);
          // this.selectedFSid = data.data.nFSid;
          // const obj = this.documentList.find(a => a.nBundledetailid == data.data?.nBundledetailid || a.nSesid == data.data?.nSesid)
          // obj.nFSid = this.selectedFSid;
          // if (obj) {
          //   if (!obj.jFSids) { obj.jFSids = []; }
          //   let find = obj.jFSids.findIndex(a => a == data.data.nFSid);
          //   if (obj && find == -1) {
          //     obj.jFSids.push(this.selectedFSid);
          //   }
          // }
          // else {
          //   if (data.data?.nSesid) {
          //     this.documentList.push({ nBundledetailid: '00000000-0000-0000-0000-000000000000', nSesid: data.data?.nSesid, nFSid: data.data.nFSid } as DocumentTab);

          //   } else {
          //     const obj = await this.individualService.getTabinfo([data.data?.nBundledetailid]);
          //     this.documentList.push(obj[0]);
          //     if (this.documentList[0]['cIsindex']) {
          //       this.titleS.setTitle('Master Index');
          //     } else {
          //       this.titleS.setTitle('Evidence');
          //     }
          //   }
          // }
          // this.cdr.detectChanges();
        }
      }
    } catch (error) {
      console.error('error in data of parent', error);
    }

    // alert(4)
  }

