  sendPresentViewerPausedEvent() {
    this.sendMessageToIframe(this.selectedTab.nBundledetailid, { event: 'PRESENT-JOINER-STATUS', data: this.isPaused }, this.compareIndex);
  }

  onTabChange() {
    // Sync QFact panel state when switching tabs so it remains open
    const qfOn = this.selectionActions.state().qf;
    const inPdfCompare = this.compareMode && (this.compareDocumentList?.length ?? 0) > 0;
    if (qfOn && (!!this.selectedTab?.nSesid || inPdfCompare)) {
      this.qfactPanelOpen = true;
    } else if (!this.selectedTab?.nSesid && !inPdfCompare) {
      this.qfactPanelOpen = false;
    }

    if (!this.nPresentid || !this.presentDetail?.isHost || this.nIndexid) return;
    // if (this.cStatus == 'L') {
    this.presentAction.emitCurrentTabData({ nBundledetailid: this.selectedTab.nBundledetailid, nPresentid: this.nPresentid, cFilename: this.selectedTab.cFilename, originalPath: this.selectedTab.originalPath, isLoaded: this.selectedTab.isLoaded, cType: this.selectedTab.cType });
    // }
  }

  emitCompare() {
    try {
      if (this.nPresentid && this.presentDetail?.isHost && !this.nIndexid) {
        this.presentAction.emitCompare({
          nPresentid: this.nPresentid, compareMode: this.compareMode, compareIndex: !this.compareMode ? 0 : this.compareIndex, compareDocumentList: !this.compareMode ? [] : this.compareDocumentList
        });
      }
    } catch (error) {
    }
  }

  emitCompareData() {
    try {
      if (this.nPresentid && this.presentDetail?.isHost && !this.nIndexid) {
        this.presentAction.emitCompareData({ nPresentid: this.nPresentid, compareMode: this.compareMode, toolBarOptions: this.toolBarOptions });
      }
    } catch (error) {
    }
  }

  private calculateScreenSize() {
    // Get pixel dimensions
    const widthPixels = window.screen.width;
    const heightPixels = window.screen.height;

    // Get device pixel ratio
    const dpr = window.devicePixelRatio || 1;

    // Calculate DPI (standard is 96, adjusted for device pixel ratio)
    const dpi = 96 * dpr;

    // Calculate physical dimensions
    const widthInches = widthPixels / dpi;
    const heightInches = heightPixels / dpi;

    // Calculate diagonal using Pythagorean theorem
    this.diagonalInches = Math.sqrt(
      Math.pow(widthInches, 2) + Math.pow(heightInches, 2)
    );

    // Check if larger than 27 inches
    this.isLargeScreen = this.diagonalInches > 27;
  }


  async refreshAllData() {
    try {
      const res: presentCurrentDetail = await this.presentSerice.getCurrentDetail(this.nPresentid);
      if (res?.msg == 1) {

        if (res.compareState || this.compareMode) {

          this.compareEvent(res.compareState);

          if (this.compareMode) {
            this.compareDocumentList.forEach((a, index) => {
              this.sendMessageToIframe(a.nBundledetailid, { event: 'REFRESH-PRESENT-POSITION', data: {} }, index + 1);
            })
          }

          if (res?.compareData?.toolBarOptions) {
            this.toolBarOptions = res.compareData.toolBarOptions;
          }
          this.cdr.detectChanges();
          // return;
        }

        if (res.status) {
          this.cStatus = res.status;
          this.presentDetail.cStatus = this.cStatus;
          this.presentDetail = { ...this.presentDetail };
          this.cdr.detectChanges();
        }

        if (res.status == 'C') {
          if (this.presentDetail?.isHost) {
            this.fallBackToPresent();
          } else {
            this.isPresentationEnded = true;
            this.cdr.detectChanges();
            return;
          }
        }
        if (!this.presentDetail?.isHost) {
          this.ss.joinPresentation(this.nPresentid, this.nUserid, this.presentDetail?.isHost);
        }
        // if (res.file) {
        if (!this.selectedTab?.nBundledetailid || (res?.file?.nBundledetailid != this.selectedTab?.nBundledetailid)) {
          this.fetchTabDocuments();
        } else {



          this.sendMessageToIframe(this.selectedTab.nBundledetailid, { event: 'REFRESH-PRESENT-POSITION', data: {} }, this.compareIndex);
        }
        // }

      } else {
        this.fetchTabDocuments();
      }
    } catch (error) {
      console.error(error);
      this.fetchTabDocuments();
    }
  }


