  /**
   * Called when an external broadcaster asks this individual-doc window to add a
   * transcript/RT session as a new tab (the session equivalent of onDocumentDraged).
   * If the session is already open, just activate it; otherwise append it to the
   * documentList and select it as the active tab.
   */
  async onSessionTabDragged(nSesid: string): Promise<void> {
    if (!nSesid) return;
    const existing = this.documentList.findIndex(d => d.nSesid === nSesid);
    if (existing > -1) {
      this.selectTab(this.documentList[existing], false, false, null);
      return;
    }

    const built = await this.buildSessionDocTab(nSesid, '00000000-0000-0000-0000-000000000000', []);
    this.documentList.push(built);
    this.selectTab(this.documentList[this.documentList.length - 1], false, false, null);
    this.refreshTabs();
    this.cdr.detectChanges();
  }

  async onDocumentDraged(nBundledetailid: string, nPage?: number, nFSid?: string, nRFSid: string = null, nRDocid: string = null, nRWebid: string = null) {
    if (!nBundledetailid) return;
    const ind = this.documentList.findIndex(a => a.nBundledetailid == nBundledetailid);
    if (ind > -1) {
      let doc = this.documentList[ind];
      if (nFSid) {
        if (!doc.jFSids) { doc.jFSids = []; }
        const find = doc.jFSids?.findIndex(a => a == nFSid);
        if (find == -1) {
          doc.jFSids.push(nFSid);
        }
      }
      if (nRFSid) { doc.nRFSid = nRFSid };
      if (nRDocid) { doc.nRDocid = nRDocid };
      if (nRWebid) { doc.nRWebid = nRWebid };
      this.documentList[ind].cPath = this.senitizeUrl(doc, nPage || null, null, null, null, doc.nRFSid || null, doc.nRDocid || null, doc.nRWebid || null);
      this.selectTab(this.documentList[ind], this.selectedFSid != null, false, nFSid);
      return;
    }

    this.presentSerice.presentMangeDocs([nBundledetailid], 'N', this.nPresentid);
    const data = await this.individualService.getTabinfo([nBundledetailid])

    data.map(a => a.cPath = this.senitizeUrl(a, nPage || null, null, null, null, a.nRFSid || null, a.nRDocid || null, a.nRWebid || null));
    // if (nFSid) { data.map(a => a.nFSid = nFSid); }
    if (nRFSid) { data.map(a => a.nRFSid = nRFSid); };
    if (nRDocid) { data.map(a => a.nRDocid = nRDocid); };
    if (nRWebid) { data.map(a => a.nRWebid = nRWebid); };


    this.documentList.push(data[0]);
    if (nFSid) {
      let doc = this.documentList[this.documentList.length - 1];
      if (!doc.jFSids) { doc.jFSids = []; }
      const find = doc.jFSids?.findIndex(a => a == nFSid);
      if (find == -1) {
        doc.jFSids.push(nFSid);
      }
      this.selectedFSid = nFSid;
    }
    this.selectTab(this.documentList[this.documentList.length - 1], this.selectedFSid != null, false, nFSid ? nFSid : null);
    this.refreshTabs();
    this.cdr.detectChanges();

  }

