    let x: DocumentTab = {
      nBundledetailid: data.nBundledetailid, cFilename: data.cFilename, originalPath: data.cPath, cPath: data.cPath, isLoaded: false, isChecked: false,
      jFSids: [], onPage: data.pg || null, currentPage: data.pg || null, nRFSid: null, nRDocid: null, nRWebid: null, jFilter: null
    };

    const idx = this.documentList.findIndex(a => a.nBundledetailid == x.nBundledetailid);

