  // }

  async handleFactSheetOpen(data: FactSheetUpdate) {
    this.selectedFSid = data?.nFSid;
    const obj = this.documentList.find(a => a.nBundledetailid == data.nBundledetailid || a.nSesid == data.nSesid)
    // obj.nFSid = data.nFSid;

    if (obj) {
      if (!obj.jFSids) { obj.jFSids = []; }
      let find = obj.jFSids.findIndex(a => a == data.nFSid);
      if (find > -1) return;
      if (obj && find == -1) {
        obj.jFSids.push(data.nFSid);
      }
    }
    else {
      if (data.nSesid) {
        this.documentList.push({ nBundledetailid: '00000000-0000-0000-0000-000000000000', nSesid: data.nSesid, jFSids: [data.nFSid] } as DocumentTab);

      } else {
        const obj = await this.individualService.getTabinfo([data.nBundledetailid]);
        this.documentList.push(obj[0]);
        if (this.documentList[0]['cIsindex']) {
          this.titleS.setTitle('Master Index');
        } else {
          this.titleS.setTitle('Evidence');
        }
      }
    }

    this.individualService.updateUrl(this.documentList, this.nCaseid, this.nPresentid, this.nIndexid);

    this.cdr.detectChanges();
  }

  closeChromeTab() {
    window.close();
  }


  demoDoclist: any[] =
    [

    ]


  addToDoctab(index: number) {
    let a = this.demoDoclist[index - 1];
    const isExist = this.documentList.findIndex(b => b.nBundledetailid == a.nBundledetailid);

    if (isExist === -1) {
      this.documentList.push(a);
    }

  }



  closeCompareMode() {
    // this.compareMode = false;
    this.onToolEvents({ event: 'COMPARE_MODE', data: false });
    this.cdr.detectChanges();
  }

  onFullScreenChange(event: boolean) {
    // this.onEvent.emit({ event: 'FULL_SCREEN_CHANGE', data: event });
    if (event == true) {
      // this.isFullScreen = true;
      this.enterFullscreen();
    }
    else {
      this.exitFullscreen();
    }
    this.cdr.detectChanges();
  }

  async enterFullscreen() {
    const root: any = document.documentElement; // or: document.body
    try {
      const req = root.requestFullscreen || root.webkitRequestFullscreen || root.msRequestFullscreen;
      if (req) await req.call(root);
    } catch (err) {
      console.error('[fullscreen] error entering:', err);
    }
  }

  async exitFullscreen() {
    const d: any = document;
    try {
      const ex = document.exitFullscreen || d.webkitExitFullscreen || d.msExitFullscreen;
      if (ex) await ex.call(document);
    } catch (err) {
      console.error('[fullscreen] error exiting:', err);
    }
  }



