import { Component, Input, Output, EventEmitter, ViewChild, ElementRef, ChangeDetectionStrategy, ChangeDetectorRef, AfterViewInit, HostListener } from '@angular/core';
import { CommonModule } from '@angular/common';
import { CalloutHighlight } from '../../../pdf/interfaces/pdf.interface';
import { IconComponent } from '../icon/icon.component';

type CalloutDrawTool = 'rect' | 'freehand' | 'arrow' | 'text' | null;

@Component({
  selector: 'app-callout-overlay',
  standalone: true,
  imports: [CommonModule, IconComponent],
  templateUrl: './callout-overlay.component.html',
  styleUrl: './callout-overlay.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush
})
export class CalloutOverlayComponent implements AfterViewInit {
  @Input() imageUrl: string = '';
  @Input() highlights: CalloutHighlight[] = [];
  @Input() isEditable: boolean = true;
  @Output() onDismiss = new EventEmitter<void>();
  @Output() onHighlightChange = new EventEmitter<CalloutHighlight[]>();

  @ViewChild('calloutImage') calloutImage: ElementRef<HTMLImageElement>;
  @ViewChild('svgOverlay') svgOverlay: ElementRef<SVGSVGElement>;
  @ViewChild('calloutContainer') calloutContainer: ElementRef<HTMLDivElement>;

  activeTool: CalloutDrawTool = null;
  activeColor: string = '#ff3d00';
  strokeWidth: number = 3;
  imgWidth: number = 0;
  imgHeight: number = 0;

  /** Display magnification applied to the captured image, expressed as a
   *  multiplier of the image's NATURAL pixel size. zoomLevel = 1.0 means
   *  the image renders 1:1 with its captured pixels (no CSS upscale =
   *  always crisp), regardless of how small the selection was. Values >1
   *  upscale (gets blurry, like any bitmap); <1 downscale (still crisp).
   *
   *  On load we set this to a dynamic default that fits the popup width:
   *  small captures land at zoom 1.0 (compact + crisp), wide captures
   *  land below 1.0 so they downscale into the popup. Stored in
   *  `dynamicDefaultZoom` so resetZoom() can return there. */
  zoomLevel: number = 1.0;
  /** Computed default zoom for the currently-loaded image. Same value the
   *  100%-label button (now relabelled as a reset) snaps back to. */
  private dynamicDefaultZoom: number = 1.0;
  private static readonly ZOOM_MIN = 0.1;
  private static readonly ZOOM_MAX = 3.0;
  private static readonly ZOOM_STEP = 0.25;

  // Drawing state
  isDrawing: boolean = false;
  currentDraw: CalloutHighlight | null = null;
  drawStartPoint: { x: number; y: number } | null = null;

  // Drag state
  isDragging: boolean = false;
  dragOffset: { x: number; y: number } = { x: 0, y: 0 };
  position: { x: number; y: number } | null = null; // null = centered via CSS

  private colorOptions = ['#ff3d00', '#ff9800', '#4caf50', '#2196f3', '#9c27b0', '#f44336', '#000000'];
  currentColorIndex: number = 0;

  constructor(private cdr: ChangeDetectorRef) {}

  ngAfterViewInit() {
    // No JS centering needed — the .callout-container's CSS top/left/
    // translate keep it centered as it resizes (image load, zoom change,
    // window resize). The .dragged modifier in the template flips off the
    // translate once the user drags, so inline pixel coords take over.
  }

  onImageLoaded() {
    if (this.calloutImage?.nativeElement) {
      this.imgWidth = this.calloutImage.nativeElement.naturalWidth;
      this.imgHeight = this.calloutImage.nativeElement.naturalHeight;
      // Default zoom = min(1.0, popupCap / naturalWidth). For small
      // captures (natural < popup) this is 1.0 → image at its true pixel
      // size, crisp. For wide captures (natural > popup) this is < 1.0
      // → image downscales to fit the popup (still crisp because the
      // source is supersampled). Either way: no CSS upscale at default.
      const popupCap = window.innerWidth * 0.96;
      this.dynamicDefaultZoom = this.imgWidth > 0
        ? Math.min(1.0, popupCap / this.imgWidth)
        : 1.0;
      this.zoomLevel = this.dynamicDefaultZoom;
      this.cdr.detectChanges();
      // No re-center needed — CSS centering follows the popup's resize.
    }
  }

  // --- Drag to move ---
  onDragStart(e: MouseEvent) {
    // Ignore mousedowns on toolbar buttons — those are intentional clicks
    // (zoom +/−, color, tool select, etc.), not drag intent. Without this
    // guard, every button click would set `position`, flip on the
    // `.dragged` class, and disable CSS-based re-centering on subsequent
    // zoom changes — leaving the popup anchored at the wrong place.
    const target = e.target as HTMLElement | null;
    if (target?.closest('button')) return;

    e.preventDefault();
    this.isDragging = true;
    const el = this.calloutContainer?.nativeElement;
    if (!el) return;
    // First drag: convert the CSS-centered layout position into pixel
    // coords so subsequent mousemoves have something to anchor against.
    if (!this.position) {
      const rect = el.getBoundingClientRect();
      this.position = { x: rect.left, y: rect.top };
    }
    this.dragOffset = {
      x: e.clientX - this.position.x,
      y: e.clientY - this.position.y
    };
  }

  @HostListener('document:mousemove', ['$event'])
  onDragMove(e: MouseEvent) {
    if (!this.isDragging) return;
    e.preventDefault();
    this.position = {
      x: e.clientX - this.dragOffset.x,
      y: e.clientY - this.dragOffset.y
    };
    this.cdr.detectChanges();
  }

  @HostListener('document:mouseup')
  onDragEnd() {
    this.isDragging = false;
  }

  setTool(tool: CalloutDrawTool) {
    this.activeTool = this.activeTool === tool ? null : tool;
    this.cdr.detectChanges();
  }

  zoomIn() {
    this.zoomLevel = Math.min(
      CalloutOverlayComponent.ZOOM_MAX,
      +(this.zoomLevel + CalloutOverlayComponent.ZOOM_STEP).toFixed(2)
    );
    this.cdr.detectChanges();
  }

  zoomOut() {
    this.zoomLevel = Math.max(
      CalloutOverlayComponent.ZOOM_MIN,
      +(this.zoomLevel - CalloutOverlayComponent.ZOOM_STEP).toFixed(2)
    );
    this.cdr.detectChanges();
  }

  resetZoom() {
    this.zoomLevel = this.dynamicDefaultZoom;
    this.cdr.detectChanges();
  }

  get canZoomIn(): boolean { return this.zoomLevel < CalloutOverlayComponent.ZOOM_MAX; }
  get canZoomOut(): boolean { return this.zoomLevel > CalloutOverlayComponent.ZOOM_MIN; }
  get zoomPercent(): number { return Math.round(this.zoomLevel * 100); }
  /** Inline `style.width.px` for the image — natural pixel width × zoom. */
  get displayWidth(): number { return Math.round(this.imgWidth * this.zoomLevel); }

  /** Container chrome: 24px horizontal padding (12 each side) + 2px wrapper
   *  border. Toolbar/header eats the vertical part instead. */
  private static readonly CHROME_HORIZONTAL = 26;
  /** Container chrome on the vertical axis: ~42px header (drag handle +
   *  buttons) + 12px padding-bottom + 2px wrapper border + 8px margin
   *  below header. Rough but close enough for "fit the image" sizing. */
  private static readonly CHROME_VERTICAL = 80;

  /** Popup container width in CSS pixels — sized to fit the captured image
   *  at its CURRENT zoom, capped at the viewport minus the 10px-each-side
   *  margin. When the user zooms in, the popup grows until it hits the
   *  viewport cap; only after that does the horizontal scrollbar appear.
   *  Zooming out shrinks the popup so it stays snug around the content.
   *  Returns 0 before the image loads so the container stays invisible
   *  (opacity-gated) and doesn't flash at viewport size. */
  get containerWidth(): number {
    if (!this.imgWidth) return 0;
    const displayed = Math.round(this.imgWidth * this.zoomLevel);
    return Math.min(
      window.innerWidth - 20,
      Math.max(320, displayed + CalloutOverlayComponent.CHROME_HORIZONTAL)
    );
  }

  /** Popup container height in CSS pixels — same idea as containerWidth
   *  but for the vertical axis. Vertical scrollbar only appears once the
   *  popup hits its viewport cap. */
  get containerHeight(): number {
    if (!this.imgHeight) return 0;
    const displayed = Math.round(this.imgHeight * this.zoomLevel);
    return Math.min(
      window.innerHeight - 20,
      Math.max(200, displayed + CalloutOverlayComponent.CHROME_VERTICAL)
    );
  }

  cycleColor() {
    this.currentColorIndex = (this.currentColorIndex + 1) % this.colorOptions.length;
    this.activeColor = this.colorOptions[this.currentColorIndex];
    this.cdr.detectChanges();
  }

  dismiss() {
    this.onDismiss.emit();
  }

  undo() {
    if (this.highlights.length > 0) {
      this.highlights = [...this.highlights.slice(0, -1)];
      this.onHighlightChange.emit(this.highlights);
      this.cdr.detectChanges();
    }
  }

  clearAll() {
    this.highlights = [];
    this.onHighlightChange.emit(this.highlights);
    this.cdr.detectChanges();
  }

  // Normalize mouse coordinates to 0-1 range relative to the image
  private getNormalizedCoords(e: MouseEvent): { x: number; y: number } {
    const img = this.calloutImage?.nativeElement;
    if (!img) return { x: 0, y: 0 };
    const rect = img.getBoundingClientRect();
    return {
      x: Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width)),
      y: Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height))
    };
  }

  onDrawStart(e: MouseEvent) {
    if (!this.isEditable || !this.activeTool) return;
    e.preventDefault();
    e.stopPropagation();

    this.isDrawing = true;
    const point = this.getNormalizedCoords(e);
    this.drawStartPoint = point;

    this.currentDraw = {
      id: crypto.randomUUID(),
      type: this.activeTool,
      color: this.activeColor,
      strokeWidth: this.strokeWidth,
      points: [point]
    };
    this.cdr.detectChanges();
  }

  onDrawMove(e: MouseEvent) {
    if (!this.isDrawing || !this.currentDraw) return;
    e.preventDefault();

    const point = this.getNormalizedCoords(e);

    if (this.currentDraw.type === 'freehand') {
      this.currentDraw.points = [...this.currentDraw.points, point];
    } else {
      this.currentDraw.points = [this.drawStartPoint, point];
    }
    this.cdr.detectChanges();
  }

  onDrawEnd(e: MouseEvent) {
    if (!this.isDrawing || !this.currentDraw) return;
    e.preventDefault();

    const point = this.getNormalizedCoords(e);

    if (this.currentDraw.type === 'freehand') {
      this.currentDraw.points = [...this.currentDraw.points, point];
    } else {
      this.currentDraw.points = [this.drawStartPoint, point];
    }

    // Only add if the shape has meaningful size
    const p = this.currentDraw.points;
    if (p.length >= 2) {
      const dx = Math.abs(p[p.length - 1].x - p[0].x);
      const dy = Math.abs(p[p.length - 1].y - p[0].y);
      if (dx > 0.005 || dy > 0.005 || this.currentDraw.type === 'freehand') {
        this.highlights = [...this.highlights, this.currentDraw];
        this.onHighlightChange.emit(this.highlights);
      }
    }

    this.isDrawing = false;
    this.currentDraw = null;
    this.drawStartPoint = null;
    this.cdr.detectChanges();
  }

  // SVG coordinate helpers
  getDisplayWidth(): number {
    return this.calloutImage?.nativeElement?.clientWidth || 0;
  }

  getDisplayHeight(): number {
    return this.calloutImage?.nativeElement?.clientHeight || 0;
  }

  toPixelX(normX: number): number {
    return normX * this.getDisplayWidth();
  }

  toPixelY(normY: number): number {
    return normY * this.getDisplayHeight();
  }

  getRectAttrs(h: CalloutHighlight): { x: number; y: number; width: number; height: number } {
    if (h.points.length < 2) return { x: 0, y: 0, width: 0, height: 0 };
    const x1 = this.toPixelX(Math.min(h.points[0].x, h.points[1].x));
    const y1 = this.toPixelY(Math.min(h.points[0].y, h.points[1].y));
    const x2 = this.toPixelX(Math.max(h.points[0].x, h.points[1].x));
    const y2 = this.toPixelY(Math.max(h.points[0].y, h.points[1].y));
    return { x: x1, y: y1, width: x2 - x1, height: y2 - y1 };
  }

  toSvgPolylinePoints(points: { x: number; y: number }[]): string {
    return points.map(p => `${this.toPixelX(p.x)},${this.toPixelY(p.y)}`).join(' ');
  }

  getArrowAttrs(h: CalloutHighlight): { x1: number; y1: number; x2: number; y2: number } {
    if (h.points.length < 2) return { x1: 0, y1: 0, x2: 0, y2: 0 };
    return {
      x1: this.toPixelX(h.points[0].x),
      y1: this.toPixelY(h.points[0].y),
      x2: this.toPixelX(h.points[1].x),
      y2: this.toPixelY(h.points[1].y)
    };
  }
}
