import { booleanAttribute, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { MatCheckboxChange, MatCheckboxModule } from '@angular/material/checkbox';
import { MatSelectModule } from '@angular/material/select';
import { NgSelectModule } from '@ng-select/ng-select';

import { AvatarComponent } from '../avatar/avatar.component';

import { IndividualService } from '../../../userpanel/services/individual/individual.service';
import { TostbarService } from '../../../core/services/tost/tostbar.service';
import { RolepermitService } from '../../../core/services/permission/rolepermit.service';

@Component({
  selector: 'shared-view-new',
  standalone: true,
  imports: [
    CommonModule,
    FormsModule,
    MatCheckboxModule,
    MatSelectModule,
    NgSelectModule,
    AvatarComponent
  ],
  templateUrl: './shared-view-new.component.html',
  styleUrl: './shared-view-new.component.scss'
})
export class SharedViewNewComponent {
  @Input() userList: any[];
  @Input() title: string = '';
  @Input() head: string;
  @Input() isSelectAll: boolean = true;
  @Input() canedit: boolean = false;
  @Input() hasshadow: boolean = true;
  @Input() haspadding: boolean = true;
  @Input() hasWrap: boolean = false;
  @Input() wrapavatar: boolean = true;
  @Input() ishorizontal: boolean = false;
  @Input() Info: string;
  @Input() fromFactSheet: boolean = false;
  @Input() isUpdate: boolean = false;
  @Input() mode: string = '';

  @Input() type: string = '';
  @Input() nCaseid: string = null;
  @Input() nId: string = null;
  @Input() nUserid: string;
  @Output() onEvent = new EventEmitter<any>();
  @Input({ transform: booleanAttribute }) adminPDisabled: boolean = false;

  @Input() viewSelected: boolean = false;
  @Input() creator: string;

  @Input() enabledEdit: boolean = false; // overwrite viewSelected

  totalUsers: number = 0;
  allSelected: boolean = false;

  // For teamshare-like UI
  activeContacts: any[] = [];
  Editall: boolean = false;
  shareall: boolean = false;
  Commentall: boolean = false;

  constructor(
    private individualS: IndividualService,
    private tost: TostbarService,
    private rolepermit: RolepermitService,
    private cdr: ChangeDetectorRef
  ) { }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['userList'] && !changes['userList'].firstChange) {
      this.normalizeUsers();
      this.updateCounts();
    }
    if (this.userList) {
      const selectedLength = this.userList.filter(f => f.isSelected).length;
      this.allSelected = (this.userList.length > 0) && (selectedLength === this.userList.length);
    }
  }

  ngOnInit() {
    this.normalizeUsers();
    this.updateCounts();
  }

  private normalizeUsers() {
    if (!Array.isArray(this.userList)) this.userList = [];
    for (const u of this.userList) {
      u.isSelected = !!u.isSelected;
      u.bCanEdit = !!u.bCanEdit;
      u.bCanReshare = !!u.bCanReshare;
      u.bCanComment = !!u.bCanComment;
    }
  }

  private updateCounts() {
    this.syncActiveContacts();
    this.updateTotalUsers();
  }

  // ----- Selection logic (same behavior as original) -----
  select(x: any) {
    if (this.viewSelected && !this.enabledEdit) return;
    x.isSelected = !x.isSelected;

    if (this.userList.filter(f => f.isSelected).length == this.userList.length) {
      this.allSelected = true;
    } else {
      this.allSelected = false;
    }
    if (x.isSelected) {
      x.bCanEdit = true;
      x.bCanReshare = true;
      x.bCanComment = true;
    } else {
      x.bCanEdit = false;
      x.bCanReshare = false;
      x.bCanComment = false;
    }
    this.syncHeaderFromRows();
    this.afterSelectionChanged(x);
  }

  private async afterSelectionChanged(sourceUser?: any) {
    this.updateCounts();

    if (this.fromFactSheet) {
      this.onEvent.emit({ type: 'USER-EDIT', data: true });
    }
    if (this.isUpdate && sourceUser) {
      await this.updateUesr(sourceUser);
      this.onEvent.emit({ type: 'UPDATE-USER-COUNT', data: this.userList.filter(f => f.isSelected).length });
    }
  }

  async updateUesr(x: any) {
    const mdl = {
      nId: this.nId,
      jUsers: JSON.stringify(this.userList.filter(f => f.isSelected).map(m => m.nUserid)),
      cType: this.type,
      nCaseid: this.nCaseid
    }
    const res = await this.individualS.update_sharelink(mdl);
    if (res) {
      if (x.isSelected) {
        this.tost.openSnackBar((this.type == 'F' ? 'Fact ' : this.type == 'D' ? 'Doc ' : 'Web ') + 'has been shared with select team member', '');
      }
    }
    this.updateTotalUsers()
  }

  selectAllUsers(e: MatCheckboxChange) {
    if (this.viewSelected && !this.enabledEdit) return;
    if (e.checked) {
      this.userList.forEach(user => {
        user.isSelected = true;
        user.bCanEdit = true;
        user.bCanReshare = true;
        user.bCanComment = true;
      });
    } else {
      this.userList.forEach(user => {
        if (this.adminPDisabled && user.isAdmin) { return; }
        user.isSelected = false;
        user.bCanEdit = false;
        user.bCanReshare = false;
        user.bCanComment = false;
      });
    }
    this.allSelected = e.checked;
    if (e.checked) {
      this.Editall = this.shareall = this.Commentall = true;
    } else {
      this.Editall = this.shareall = this.Commentall = false;
    }
    this.syncHeaderFromRows();
    const first = this.userList[0];
    if (first) {
      this.updateUesr(first);
    }
    if (this.fromFactSheet) {
      this.onEvent.emit({ type: 'USER-EDIT', data: true });
    }
    this.updateCounts();
  }

  // ----- UI helpers -----
  syncActiveContacts() {
    this.activeContacts = (this.userList ?? []).filter(u => u.isSelected);
    this.cdr.detectChanges();
  }

  updateTotalUsers() {
    this.totalUsers = this.userList.filter(a => (a.isSelected && this.viewSelected) || !this.viewSelected)?.length
    this.cdr.detectChanges();
  }

  // ----- Teamshare-like handlers -----
  checkRow(ev: MatCheckboxChange, u: any) {
    u.isSelected = ev.checked;
    if (!ev.checked) {
      u.bCanEdit = false;
      u.bCanReshare = false;
      u.bCanComment = false;
    } else {
      u.bCanEdit = true;
      u.bCanReshare = true;
      u.bCanComment = true;
    }
    this.allSelected = (this.userList?.length ?? 0) > 0 && this.userList.every(x => x.isSelected);
    this.syncHeaderFromRows();
    this.afterSelectionChanged(u);
  }

  onChangeAll(val: boolean, type: 'E' | 'S' | 'CM'): void {
    if (type == 'E') {
      this.Editall = val;
    } else if (type == 'S') {
      this.shareall = val;
    } else if (type == 'CM') {
      this.Commentall = val;
    }
    for (const u of this.userList ?? []) {
      if (this.adminPDisabled && u.isAdmin && !val) { continue; }
      if (u.isSelected) {
        if (type == 'E') u.bCanEdit = this.Editall;
        else if (type == 'S') u.bCanReshare = this.shareall;
        else if (type == 'CM') u.bCanComment = this.Commentall;
      }
    }
  }

  syncHeaderFromRows(): void {
    const sel = (this.userList ?? []).filter(u => u.isSelected);
    if (sel.length === 0) {
      this.Editall = this.shareall = this.Commentall = false;
      return;
    }
    this.Editall = sel.every(u => !!u.bCanEdit);
    this.shareall = sel.every(u => !!u.bCanReshare);
    this.Commentall = sel.every(u => !!u.bCanComment);
  }
}


