import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output, SimpleChanges, ViewEncapsulation } from '@angular/core';
import { DocumentTab } from '../../../interfaces/individual.interface';
import { IconComponent } from '../../../../shared/components/icon/icon.component';
import { CommonModule } from '@angular/common';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FormsModule } from '@angular/forms';

@Component({
  selector: 'doctab',
  standalone: true,
  // changeDetection: ChangeDetectionStrategy.OnPush,
  imports: [IconComponent, CommonModule, MatCheckboxModule, FormsModule],
  templateUrl: './doctab.component.html',
  styleUrl: './doctab.component.scss',
  encapsulation: ViewEncapsulation.Emulated
})
export class DoctabComponent {
  @Input() data: DocumentTab;
  @Input() active: boolean = false;
  @Input() compareMode: boolean = false;
  @Input() name: string;
  @Input() isFactsheet: boolean = false;
  @Input() isChecked: boolean = false;
  @Input() nFSid: string;
  @Input() isClose: boolean = true;
  @Input() linkexplorerMode: boolean = false;
  @Input() compareDocumentList: DocumentTab[] = [];
  @Input() length: any = 0;
  @Input() nPresentid: string;
  @Input() isHost: boolean;
  @Output() onClose = new EventEmitter<void>();
  @Output() onChecked = new EventEmitter<boolean>();
  constructor(private cdr: ChangeDetectorRef) {

  }

  ngOnChanges(changes: SimpleChanges) {
    if (changes["isChecked"]) {
      this.isChecked = this.isChecked;
      this.cdr.detectChanges();
    }
    return;
  }


  closeTab() {
    this.onClose.emit();
  }

  OnChnageEvent(event: any) {
    this.onChecked.emit(this.isChecked);
  }

  ngOnInit() {
    if (this.isFactsheet && this.nFSid) {
      this.name = 'Fact Sheet';
      this.cdr.detectChanges();
    }
  }

  checkdisable(checbox) {
    checbox.checked = false;
    this.onChecked.emit(this.isChecked);
  }

}