import { booleanAttribute, Component, EventEmitter, Input, Output } from '@angular/core';
import { MatDialog } from '@angular/material/dialog';
import { TaskFormComponent } from '../task-form/task-form.component';
import { selectedTaskList } from '../../../interfaces/issue.interface';
import { AvatarComponent } from "../../avatar/avatar.component";
import { MatTooltipModule } from '@angular/material/tooltip';
import { ButtonComponent } from "../../button/button.component";
import { IconComponent } from "../../icon/icon.component";
import { DatePipe } from '@angular/common';

@Component({
  selector: 'selected-tasks-list',
  standalone: true,
  imports: [AvatarComponent, MatTooltipModule, ButtonComponent, IconComponent, DatePipe],
  templateUrl: './selected-tasks-list.component.html',
  styleUrl: './selected-tasks-list.component.scss'
})
export class SelectedTasksListComponent {

  @Input() selectedTasks: any[];
  @Input() canedit: boolean = false;
  @Input({ transform: booleanAttribute }) showreminder: boolean = false;
  @Input() hasshadow: boolean = false;
  @Input() nCaseid: string;
  @Input() ismyfiles: boolean = false;
  @Input() canDelete: boolean = false;
  editask: boolean = false;
  @Output() OnEvent = new EventEmitter();
  dialogRef: any;
  choosedtask: selectedTaskList;
  @Input() isGrid: boolean = false;
  constructor(private dialog: MatDialog,) {

  }


  removeTask(x, ind) {
    this.selectedTasks.splice(ind, 1);
    this.OnEvent.emit({ event: 'DELETE', data: { nTaskid: x.nTaskid } });
  }


  edit(x) {
    this.dialogRef = this.dialog.open(TaskFormComponent, {
      width: !this.ismyfiles ? '420px' : '436px',
      height: !this.ismyfiles ? 'calc(100vh - 56px)' : 'calc(100% - 220px)',
      position: !this.ismyfiles ? { right: '0vh', top: '56px' } : { right: '24px', top: '200px' },
      hasBackdrop: false,
      panelClass: 'noshadow'
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.editable_list = x;
    this.dialogRef.afterClosed().subscribe(result => {
      this.dialogRef = null;
      if (result) {
        // this.isLoading = true;
        // this.ngOnInit();
        this.OnEvent.emit({ event: 'RELOAD', data: { nTaskid: x.nTaskid } });
      }
    });
  }

}
