import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { IconComponent } from '../../../../../../shared/components/icon/icon.component';
import { ButtonComponent } from '../../../../../../shared/components/button/button.component';
import { IssueListComponent } from '../../../../../../rt/components/issues/issue-list/issue-list.component';
import { factIssues } from '../../../../../../shared/interfaces/fact.interface';
import { issueManagerEvents, selectedIssues } from '../../../../../../rt/interfaces/issue.interface';
import { activeFormType } from '../../fact-sheet/fact-sheet.component';
import { IssueManageComponent } from "../../../../../../rt/components/issues/issue-manage/issue-manage.component";

@Component({
  selector: 'form-issue',
  standalone: true,
  imports: [IconComponent, ButtonComponent, IssueListComponent, IssueManageComponent],
  templateUrl: './issue.component.html',
  styleUrl: './issue.component.scss'
})
export class IssueComponent {

  @Input() activeForm: activeFormType;
  @Output() activeFormChange: EventEmitter<activeFormType> = new EventEmitter<activeFormType>();

  @Input() factIssues: factIssues[];
  @Output() factIssuesChange: EventEmitter<factIssues[]> = new EventEmitter<factIssues[]>();




  // selectedIssues: selectedIssues[] = [];

  private _selectedIssues: selectedIssues[] = [];
  get selectedIssues(): selectedIssues[] {
    return this._selectedIssues;
  }
  set selectedIssues(value: selectedIssues[]) {
    this._selectedIssues = value;
    this.factIssuesChange.emit(this._selectedIssues as any);
  }



  @Input() nCaseid: string;
  @Input() nUserid: string;

  visibleIssueModel: boolean;
  ngOnInit(): void {
    this.setToSelection();
  }

  ngOnChanges(changes: SimpleChanges): void {
    if (changes['changes'] && !changes['changes'].firstChange) {
      // factIssues
      this.setToSelection();
    }
  }


  setToSelection() {
    this.selectedIssues = this.factIssues as any;
  }



  close() {
    this.activeFormChange.emit(null);
  }

  openIssueManager() {
    this.visibleIssueModel = true;
    this.activeFormChange.emit('I');
  }

  issueManagerEmit(event: issueManagerEvents) {
    if (event.event === 'CLOSE') {
      this.visibleIssueModel = false;
    }
  }
}
