import { Component, EventEmitter, Input, Output, SimpleChanges } from '@angular/core';
import { FactsheetService } from '../../../../services/factsheet/factsheet.service';
import { factContacts, factDetail, factShared, factTasks } from '../../../../interfaces/factsheet.interface';
import { SecureStorageService } from '../../../../../core/services/storage/secure-storage.service';
import { MatMenuModule } from '@angular/material/menu';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { SharedViewComponent } from '../../../../../shared/components/shared-view/shared-view.component';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { SelectedIssuesComponent } from '../../../../../shared/components/issues/selected-issues/selected-issues.component';
import { factIssues } from '../../../../../shared/interfaces/fact.interface';
import { IssueComponent } from '../forms/issue/issue.component';
import { FactNoteComponent } from '../../../../../pdf/components/facts/fact-note/fact-note.component';
import { FactboxComponent } from '../../../../../pdf/components/facts/factbox/factbox.component';
import { EmptyComponent } from '../../../../../shared/components/empty/empty.component';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { MatDialog } from '@angular/material/dialog';
// Lazy-loaded inside addFactlink() to break an ES-module cycle with feed-display.
import type { FileexplorerComponent } from '../../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { SelectedTasksComponent } from '../../../../../shared/components/tasks/selected-tasks/selected-tasks.component';
import { factEvents, selectedTaskItem } from '../../../../../marking/interfaces/fact.interface';
import { AssignFactTaskComponent } from '../../../../../marking/components/fact/assign-fact-task/assign-fact-task.component';
import { AssignContactComponent } from '../../../../../marking/components/fact/assign-contact/assign-contact.component';
import { selectedContactList } from '../../../../../shared/interfaces/issue.interface';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { NavContactviewComponent } from '../../../../../rt/components/mark-nav/nav-components/nav-contactview/nav-contactview.component';
import { FormBuilder, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { MatSelectModule } from '@angular/material/select';
import { codeData } from '../../../../../shared/interfaces/common.interface';
import { CommonService } from '../../../../../shared/services/common/common.service';
import { DateFormComponent, jDateType } from '../../../../../marking/components/fact/date-form/date-form.component';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { SelectedTasksListComponent } from "../../../../../shared/components/tasks/selected-tasks-list/selected-tasks-list.component";
import { QuickPreviewComponent } from "../../../quick-preview/quick-preview.component";
import { BroadcastingService } from '../../../../../core/services/broadcasting/broadcasting.service';
import { FACTFROM } from '../../../../../pdf/interfaces/pdf.interface';
import { FactDiscussComponent } from "../../../comment/fact-discuss/fact-discuss.component";
import { TeamshareComponent } from '../../../../../marking/components/fact/teamshare/teamshare.component';
import { SharedViewNewComponent } from '../../../../../shared/components/shared-view-new/shared-view-new.component';


export type activeFormType = 'I' | 'T' | 'TF' | 'C' | 'CF' | null;

@Component({
  selector: 'rt-fact-sheet',
  standalone: true,
  imports: [MatMenuModule, ButtonComponent, IconComponent, SharedViewComponent, BadgeComponent, SelectedIssuesComponent,
    IssueComponent, FactNoteComponent, FactboxComponent, EmptyComponent, SourceCardComponent,
    AssignFactTaskComponent, AssignContactComponent, AvatarComponent, NavContactviewComponent,
    MatSelectModule, ReactiveFormsModule, DateFormComponent, SelectedTasksListComponent, QuickPreviewComponent, FactDiscussComponent, SharedViewNewComponent],
  templateUrl: './fact-sheet.component.html',
  styleUrl: './fact-sheet.component.scss'
})
export class FactSheetComponent {

  @Input() cFFrom: FACTFROM = 'RT';

  @Input() nFSid: string;
  @Input() nSesid: string;
  @Input() nCaseid: string;
  @Input()


  @Input() nBundledetailid: string;


  factDetail: factDetail = {} as factDetail;
  factShared: factShared[] = [];
  factSharedOriginals: factShared[] = [];
  factIssues: factIssues[] = [];
  factContacts: selectedContactList[] = [];
  factTasks: selectedTaskItem[] = [];

  factLinks: any[] = []




  editModeEnabled: boolean = false;
  @Input() nUserid: string;

  isLoading: boolean = true;

  activeForm: activeFormType;
  dialogRef: any;
  frm: FormGroup;

  filetypeList: codeData[] = [];
  statusList: codeData[] = [];
  jDate: jDateType;

  isSaving: boolean = false;

  _saved: boolean = false;
  saved = () => {
    this._saved = true;
    setTimeout(() => {
      this._saved = false;
      this.editModeEnabled = false;
    }, 2000);
  }

  // factUserDetail: factShared;

  nTaskid: string;

  nContactid: string;

  curruntfact: any;

  @Output() onEvent = new EventEmitter<any>();

  bHavePermission: boolean = false;

  cFormPermission: string = 'N';
  canEditContact = false;
  canDeleteContact = false;
  canViewContact = false;

  updatePermission(perm: { canEdit: boolean; canDelete: boolean; canView: boolean }) {
    console.log('permission from contact', perm);
    this.canEditContact = perm.canEdit;
    this.canDeleteContact = perm.canDelete;
    this.canViewContact = perm.canView;
  }

  // cFormPermission: string = 'N';

  constructor(private readonly factsheetService: FactsheetService, private dialog: MatDialog, private fb: FormBuilder, private common: CommonService, private tost: TostbarService, private broadCastService: BroadcastingService) {

  }

  async ngOnInit() {
    if (!this.nFSid) {
      this.isLoading = false;
      return;
    }


    this.frm = this.fb.group({
      nFiletype: [0, Validators.required],
      nStatus: [0, Validators.required],
    })

    this.statusList = await this.common.getCode(24);
    this.filetypeList = await this.common.getCode(23);
    this.loadFactDetail();
  }

  private async loadFactDetail() {
    try {
      this.factDetail = await this.factsheetService.getFactDetail(this.nFSid);
      // console.info('Fact Detail', this.factDetail)
      if (!this.factDetail?.bCanView) {
        this.isLoading = false;

        return;
      }
      this.jDate = this.factDetail.jDate || { type: "D", nValue: 0, cValue: 'On', record: [] };


      this.frm.patchValue({
        nFiletype: this.factDetail?.nFiletype,
        nStatus: this.factDetail?.nStatus
      })
      this.loadFactShared();
      this.loadFactIssues();
      this.loadFactContacts();
      this.loadFactLinks();
      this.loadFactTasks();
      this.isLoading = false;
    } catch (error) {
      console.error('Error loading fact detail:', error);
    }
  }

  private async loadFactShared() {
    try {
      const users = await this.factsheetService.getFactShared(this.nFSid);

      this.factShared = users.filter(a => a.nUserid != this.factDetail?.nUserid && a.nUserid != this.nUserid);
      this.factSharedOriginals = JSON.parse(JSON.stringify(this.factShared));
      /* if (this.factShared?.length) {
         this.factUserDetail = this.factShared.find(a => a.nUserid == this.nUserid);
         this.bHavePermission = this.factUserDetail?.bCanEdit || this.factUserDetail?.bCanReshare || this.factUserDetail?.bCanComment;
 
       }*/

      // if (this.factShared?.length) {
      //   this.factShared = this.factShared.filter(a => a.nUserid != this.nUserid)
      // }


    } catch (error) {
      console.error('Error loading fact issues:', error);
    }
  }


  private async loadFactIssues() {
    try {
      this.factIssues = await this.factsheetService.getFactIssues(this.nFSid);
    } catch (error) {
      console.error('Error loading fact issues:', error);
    }
  }

  private async loadFactContacts() {
    try {
      this.factContacts = await this.factsheetService.getFactContacts(this.nFSid);
    } catch (error) {
      console.error('Error loading fact contacts:', error);
    }
  }

  private async loadFactTasks() {
    try {
      const res = await this.factsheetService.getFactTasks(this.nFSid);
      this.factTasks = res[0] || [];
      if (this.factTasks?.length) {
        const teams = res[1] || [];
        const taskReminder = res[2] || [];

        for (let x of this.factTasks) {
          x.teamlist = [];
          const obj = teams.filter(a => a.nTaskid == x.nTaskid);
          const reminder = taskReminder.find((a: selectedTaskItem) => a.nTaskid == x.nTaskid);

          if (obj?.length) {
            x.teamlist = obj;
          }
          if (reminder) {
            x.dReminderDt = reminder.dReminderDt;
          }
        }
      }
    } catch (error) {
      console.error('Error loading fact tasks:', error);
    }
  }

  private async loadFactLinks() {
    try {
      this.factLinks = await this.factsheetService.getFactLinks(this.nFSid);
    } catch (error) {
      console.error('Error loading fact tasks:', error);
    }
  }


  closeEditMode() {
    this.editModeEnabled = false
    this.ngOnInit()
    // RESET ALL VALUES();
  }


  OnIssueChange(e) {
    this.factIssues = [...e];

    console.log('factIssues', this.factIssues);
  }


  updatejtext(ev) {
    // this.isEdited = true;
  }



  OnDateChange(ev) {
    this.factDetail.jDate = ev;
    console.log(this.frm.value);
  }

  async addFactlink() {
    if (this.dialogRef) return;
    // Lazy-load FileexplorerComponent to avoid ES module cycle at import time.
    const { FileexplorerComponent: FileexplorerCmp } = await import(
      '../../../../../shared/components/myfiles/fileexplorer/fileexplorer.component'
    );
    this.dialogRef = this.dialog.open(FileexplorerCmp, {
      width: '90vw',
      height: '90vh',
      panelClass: ['rounded-xl', 'overflow-hidden'], // Rounded corners
      disableClose: true
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.isChooser = true;
    this.dialogRef.componentInstance.isIndividual = true;
    this.dialogRef.componentInstance.isLink = 'F';
    this.dialogRef.componentInstance.isDownload = true; // Show Save button
    this.dialogRef.componentInstance.disabledFiles = this.factLinks.map(a => a.nBundledetailid);
    this.dialogRef.afterClosed().subscribe(result => {
      try {
        const files = this.dialogRef.componentInstance.choosedFile;
        this.factLinks = [...this.factLinks, ...files];
        // this.jFilesChange.emit(this.jFiles);
      } catch (error) {
      }
      this.dialogRef = null;
    });
  }



  OnFilesEvnets(e: any, i: number) {

    if (e.type == 'D') {
      this.factLinks.splice(i, 1);
    }

    if (e.type == 'OPEN-PREVIEW') {
      this.selctfactlink(e.data)
    }

  }





  async lastID(): Promise<string> {
    let lastId: any = 0;
    this.factIssues.map(a => a.nIid = a.nIid || a.nIssueid);
    let lastdata = await this.common.getcolorid(this.factIssues);
    if (lastdata.length) {
      lastId = lastdata[0]["nIid"];
    } else {
      lastId = this.factIssues[this.factIssues.length - 1]["nIid"] || 0
    }
    return lastId ? lastId : '';
  }


  async submitForm() {
    debugger;
    if (this.frm.invalid || !this.factDetail?.bCanEdit) return;

    let colorid = this.factDetail?.nColorid;

    colorid = await this.lastID();
    if (!colorid) {
      console.error('Last Issue (nColorid) not found using previous one')
      colorid = this.factDetail?.nColorid;
    }

    const jFl = this.convToStr(this.getSelectedFiles());
    const jIssues = this.convToStr(this.factIssues.map(a => ({ nIid: a.nIid, nImpactid: (a.nImpactid || 0), nRelid: (a.nRelid || a.nRelevanceid || 0) })));
    const jContacts = this.convToStr(this.factContacts.map(a => ({ c: a.nContactid })));
    const jTasks = this.convToStr(this.factTasks.map(a => ({ t: a.nTaskid })))

    const formValue = this.frm.value;
    const mdl: any = {
      nFSid: this.nFSid,
      nColorid: colorid,
      nFt: formValue.nFiletype,
      nSt: formValue.nStatus,
      jFl,
      jIssues,
      jContacts,
      jTasks,
      jDate: this.convToStr(this.jDate),
      jT: JSON.stringify(this.factDetail.jTexts || '[]'),
      bIsUserUpdated: this.isUserUpdated()
    }

    if (this.factDetail?.bCanReshare && mdl.bIsUserUpdated) {
      const jUsers = this.convToStr(this.getSelectedUsers());
      mdl.jUsers = jUsers;
    }

    if (this.cFFrom == 'I') {
      mdl.nBundledetailid = this.nBundledetailid;
    } else {
      mdl.nSesid = this.nSesid;
    }
    this.isSaving = true;
    const res = await this.factsheetService.saveFact(mdl);

    this.isSaving = false;
    if (res.msg == 1) {

      this.tost.success(res.value);
      this.activeForm = null;
      this.saved();
      // this.closeEditMode();
      // this.ngOnInit();
    } else {
      this.tost.error(res.value || 'Failed to save');
    }
  }


  convToStr(val: any) {
    return JSON.stringify(val);
  }


  getSelectedFiles() {
    return this.factLinks.map((a) => ({ b: a.nBundledetailid, Linktype: a.jLinktype }))
  }


  getSelectedUsers() {

    const fixedUsers = this.factSharedOriginals.filter(a => a.nUserid == this.factDetail?.nUserid || a.nUserid == this.nUserid);

    const usr = this.factShared.filter(f => f.isSelected).map(m => ({
      nUserid: m.nUserid,
      bCanEdit: m.bCanEdit,
      bCanCopy: m.bCanCopy,
      bCanReshare: m.bCanReshare,
      bCanComment: m.bCanComment
    }));


    fixedUsers.forEach(a => {
      const obj = usr.find(m => m.nUserid == a.nUserid);
      if (obj) {
        obj.nUserid = a.nUserid;
        obj.bCanEdit = a.bCanEdit;
        obj.bCanCopy = a.bCanCopy;
        obj.bCanReshare = a.bCanReshare;
        obj.bCanComment = a.bCanComment
      } else {
        usr.push({
          nUserid: a.nUserid,
          bCanEdit: a.bCanEdit,
          bCanCopy: a.bCanCopy,
          bCanReshare: a.bCanReshare,
          bCanComment: a.bCanComment
        })
      }
    })



    return usr;
  }

  handleEvents(ev: factEvents) {
    if (ev.event == 'CLOSE') {
      this.activeForm = null;
    }
  }


  async unshareWithMe() {
    const res = await this.factsheetService.unshare(this.nFSid);
    if (res.success) {
      this.broadCastService.portMessage({ event: 'INDIVIDUAL-FACT-SHEET-DELETE', data: { nFSid: this.nFSid } });
      // window.close();
      this.onEvent.emit({ event: 'DELETE-FACT', data: { nFSid: this.nFSid } });
      this.tost.success(res.value);
    } else {
      this.tost.error(res.value);
    }
  }


  async deleteFactSheet() {
    const res = await this.factsheetService.delete(this.nFSid);
    if (res.msg == 1) {
      this.broadCastService.portMessage({ event: 'INDIVIDUAL-FACT-SHEET-DELETE', data: { nFSid: this.nFSid } });
      this.onEvent.emit({ event: 'DELETE-FACT', data: { nFSid: this.nFSid } });
      // window.close();
      this.tost.success(res.value);
    } else {
      this.tost.error(res.value);
    }
  }


  removeContact(x: selectedContactList, index: number) {
    this.factContacts.splice(index, 1);
  }


  selctfactlink(x: any) {
    x.isSelected = !x.isSelected;
    this.curruntfact = x;
  }

  OnQuickPreviewEvent(e) {
    this.onEvent.emit({ event: 'OPEN-FACT-FROM-FACT-SHEET', data: e.data });
  }

  deselect() {
    this.curruntfact = null;
    this.factLinks.forEach((item) => {
      item.isSelected = false;
    });
  }

  findkey(list: codeData[], value: number) {
    return list.find(a => a.nValue == value)?.cKey;
  }



  openForm(type: 'N' | 'E', formType: 'T' | 'C') {

    if (formType == 'T') {
      this.activeForm = 'TF'
      if (type == 'N') {
        this.nTaskid = null;
        this.cFormPermission = 'N';
      } else {
        this.cFormPermission = 'E';
      }
    }
    else if (formType == 'C') {
      this.activeForm = 'CF'
      if (type == 'N') {
        this.nContactid = null;
        this.cFormPermission = 'N';
        // this.cContactFormPermission = 'N';
      }
      else {
        this.cFormPermission = 'E';
        // this.cContactFormPermission = 'E';
      }

    }

  }


  isUserUpdated(): boolean {
    if (this.factShared.length !== this.factSharedOriginals.length) {
      return true;
    }

    return this.factShared.some((user, index) => {
      const original = this.factSharedOriginals[index];
      return (
        user.isSelected != original.isSelected ||
        user.bCanComment != original.bCanComment ||
        user.bCanCopy != original.bCanCopy ||
        user.bCanEdit != original.bCanEdit ||
        user.bCanReshare != original.bCanReshare
      );
    });
  }

  closeTab() {
    window.close()
  }

}
