import { ChangeDetectionStrategy, ChangeDetectorRef, Component, EventEmitter, Input, Output } from '@angular/core';
import { ButtonComponent } from '../../../../../shared/components/button/button.component';
import { IconComponent } from '../../../../../shared/components/icon/icon.component';
import { MatMenuModule } from '@angular/material/menu';
import { AvatarComponent } from '../../../../../shared/components/avatar/avatar.component';
import { EmptyComponent } from '../../../../../shared/components/empty/empty.component';
import { SourceCardComponent } from '../../../../../shared/components/source-card/source-card.component';
import { BadgeComponent } from '../../../../../shared/components/badge/badge.component';
import { CommonModule } from '@angular/common';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatSelectModule } from '@angular/material/select';
import { codeData } from '../../../../../shared/interfaces/common.interface';
import { CommonService } from '../../../../../shared/services/common/common.service';
import { FormBuilder, FormControl, FormGroup, ReactiveFormsModule, Validators } from '@angular/forms';
import { DocInfo, myTeamUsers, toolEvents } from '../../../../../pdf/interfaces/pdf.interface';
import { DatetimeComponent } from '../../../../../shared/components/datetime/datetime.component';
import { FactService } from '../../../../../shared/services/fact/fact.service';
import { MatDialog } from '@angular/material/dialog';
import { PdfDataService } from '../../../../../pdf/service/pdf-data.service';
import { factdata, factIssues, factlinkfiles } from '../../../../../shared/interfaces/fact.interface';
import { TostbarService } from '../../../../../core/services/tost/tostbar.service';
import { SharedViewComponent } from '../../../../../shared/components/shared-view/shared-view.component';
import { NgxPaginationModule } from 'ngx-pagination';
import { SelectedIssuesComponent } from '../../../../../shared/components/issues/selected-issues/selected-issues.component';
import { selectedContactList, selectedTaskList } from '../../../../../shared/interfaces/issue.interface';
import { SelectedTasksComponent } from '../../../../../shared/components/tasks/selected-tasks/selected-tasks.component';
import { SelectedContactComponent } from '../../../../../shared/components/contacts/selected-contact/selected-contact.component';
import { DetailformComponent } from '../detailform/detailform.component';
import { formType } from '../../../../interfaces/individual.interface';
import { Subject } from 'rxjs';
import { FileexplorerComponent } from '../../../../../shared/components/myfiles/fileexplorer/fileexplorer.component';
import { MatTooltipModule } from '@angular/material/tooltip';
import { PreviewComponent } from '../../../../../shared/components/myfiles/preview/preview.component';
import { SecureStorageService } from '../../../../../core/services/storage/secure-storage.service';
import { FactNoteComponent } from '../../../../../pdf/components/facts/fact-note/fact-note.component';
import { MatCheckboxModule } from '@angular/material/checkbox';
import { FactboxComponent } from '../../../../../pdf/components/facts/factbox/factbox.component';
import { QuickPreviewComponent } from '../../../quick-preview/quick-preview.component';

@Component({
  selector: 'app-factsheet',
  standalone: true,
  changeDetection: ChangeDetectionStrategy.Default,
  imports: [MatFormFieldModule, MatSelectModule, CommonModule, SharedViewComponent, NgxPaginationModule,
    ButtonComponent, IconComponent, MatMenuModule, ReactiveFormsModule,
    EmptyComponent, SourceCardComponent, BadgeComponent, DatetimeComponent, SelectedIssuesComponent, SelectedTasksComponent, SelectedContactComponent, DetailformComponent,
    MatTooltipModule, PreviewComponent, MatCheckboxModule, FactNoteComponent, FactboxComponent, QuickPreviewComponent],
  templateUrl: './factsheet.component.html',
  styleUrl: './factsheet.component.scss'
})
export class FactsheetComponent {

  @Input() nFSid: string | null;
  @Input() nBundledetailid: string;
  @Input() nCaseid: string;
  @Output() onEvent = new EventEmitter<any>();
  docInfo: DocInfo;
  factData: factdata = {} as factdata;
  userList: myTeamUsers[] = [];
  selectedUsr: myTeamUsers[] = [];
  jOText: string[] = [];
  jTexts: string[] = [];
  NewjTexts: string[] = [];
  issueList: factIssues[] = [];
  linkfiles: factlinkfiles[] = [];
  taskList: selectedTaskList[] = [];
  contactList: selectedContactList[] = [];
  nCurrent_annot: number = 1;
  FormType: formType = null;
  notebox: boolean = false;
  isDetailLoaded: boolean = false;
  issaved: boolean = false;
  isIssueAndLinkLoaded: boolean = false;
  isContactLoaded: boolean = false;
  isTaskLoaded: boolean = false;
  bIsHighlighted: boolean = false;

  @Input() onIndividualEvent: Subject<any>;
  curruntfact: any;

  isEdit: boolean = false;
  editUser: boolean = false;
  isEdited: boolean = false;

  timezoneList: codeData[] = [];
  filetypeList: codeData[] = [];
  statusList: codeData[] = [];
  dateList: codeData[] = [];

  chngtmzone: boolean = false;
  usrtmzone: any;
  frm: FormGroup;
  dialogRef: any;

  isFactUpdating: boolean = false;
  isDeleting: boolean = false;
  quickPreviewFiles: any = [];
  previewMode: boolean = false;
  nUserid: string;
  constructor(private secure: SecureStorageService, private pdfData: PdfDataService, private tost: TostbarService, private cdr: ChangeDetectorRef
    , private factService: FactService, private common: CommonService, private formBuilder: FormBuilder, private dialog: MatDialog) { }

  async ngOnInit() {

    this.frm = this.formBuilder.group({
      nFSid: [this.nFSid, [Validators.required]],
      nTZid: [, [Validators.required]],
      nFiletype: [, [Validators.required]],
      nStatus: [, [Validators.required]],
      jDate: new FormGroup({
        type: new FormControl(207),
        date1: new FormControl(''),
        date2: new FormControl('')
      })
    });

    try {
      this.nUserid = await this.secure.getUserId();
      if (this.onIndividualEvent) {
        this.onIndividualEvent.subscribe((e: toolEvents) => {
          if (e.event == 'REFRESH-BIGFACT') {
            this.reloadFactSheet();
          } else if (e.event == 'ON-CONVERT-TO-PAGE-LEVEL') {

            this.convertToPageLevel(e.data)
          }
        })
      }

    } catch (error) {

    }

    this.startFetchingData();
  }

  emitData(e) {
    if (e.type == 'USER-EDIT') {
      this.isEdited = e.data;
    }
  }

  viewQuickPreview(x) {
    // Find the index of the item in the quickPreviewFiles array
    const ind = this.quickPreviewFiles.findIndex(a => a.nBundledetailid === x.nBundledetailid);
    if (ind > -1) {
      // If the item is found, deactivate and remove it from the array
      this.quickPreviewFiles[ind].active = false;
      this.quickPreviewFiles.splice(ind, 1);
    } else {
      // If the item is not found, activate and add it to the array
      x.active = true;
      this.quickPreviewFiles.push(x);
    }
    this.cdr.markForCheck();
    this.cdr.detectChanges();
  }


  reloadFactSheet() {
    this.isDetailLoaded = false;
    this.cdr.detectChanges();
    this.startFetchingData();
  }



  async startFetchingData() {
    const data = await this.pdfData.fetchDocInfo(this.nBundledetailid);
    this.docInfo = data;
    const Factdata = await this.factService.getFactDetails([this.nFSid]);
    if (Factdata && Factdata.length > 0) {
      this.factData = Factdata[0];
      this.bIsHighlighted = this.factData.bIsHighlighted;
      this.cdr.detectChanges();
    } else {
      this.tost.error('No Fact Found');
    }

    this.jOText = this.factData.jOT || [];
    this.jTexts = this.factData.jTexts || [];
    this.userList = await this.common.getMyTeamUsers(this.nCaseid);
    this.isDetailLoaded = true;
    this.cdr.detectChanges();
    this.getOtherDetails();
    this.frm = this.formBuilder.group({
      nFSid: [this.nFSid, [Validators.required]],
      nTZid: [this.factData.nTZid, [Validators.required]],
      nFiletype: [this.factData.nFiletype, [Validators.required]],
      nStatus: [this.factData.nStatus, [Validators.required]],
      jDate: new FormGroup({
        type: new FormControl((this.factData?.jDate?.type) || 207),
        date1: new FormControl((this.factData?.jDate?.date1) || ''),
        date2: new FormControl((this.factData?.jDate?.date2) || '')
      })
    });

    this.fillForm();

    this.initData();


  }



  fillForm() {
    this.frm.patchValue({
      nBundledetailid: this.nBundledetailid,
      nTZid: this.factData.nTZid,
      nFiletype: this.factData.nFiletype,
      nStatus: this.factData.nStatus,
      jDate: {
        type: this.factData.jDate.type,
        date1: this.factData.jDate.date1,
        date2: this.factData.jDate.date2
      }
    })
  }

  changePaginatePage(e: any) {
    this.nCurrent_annot = e;
  }

  getOtherDetails() {
    this.fetchIssuesAndLinks();
    this.fetchSharedList();
    this.fetchTaskList();
    this.fetchContactList();
  }

  async fetchSharedList() {
    this.selectedUsr = await this.factService.getFactShare(this.nFSid);
    this.userList.map(a => a.isSelected = (this.selectedUsr.findIndex(b => b.nUserid == a.nUserid) > -1));
    this.userList = [...this.userList];
    this.cdr.detectChanges();
  }

  async fetchTaskList() {

    this.isTaskLoaded = false;
    this.cdr.detectChanges();
    const res: any = await this.factService.getFactTask(this.nFSid);
    this.taskList = res[0] || [];
    this.taskList.map(a => {
      var user = [];
      if (res[1]) {
        user = res[1].filter(b => b.jTaskid.includes(a.nTaskid));
      }
      a['teamlist'] = user ? user : [];
    });
    this.taskList.map(a => {
      var remiders = [];
      if (res[2]) {
        let row = res[2].filter(b => b.nTaskid == a.nTaskid);
        remiders = row.length ? row[0].jReminders : [];
      }
      a['jReminders'] = remiders ? remiders : [];
    });

    console.log('task list with reminders', this.taskList);

    this.isTaskLoaded = true;
    this.cdr.detectChanges();
  }

  async fetchContactList() {
    this.isContactLoaded = false;
    this.cdr.detectChanges();
    this.contactList = await this.factService.getFactContact(this.nFSid);
    this.isContactLoaded = true;
    this.cdr.detectChanges();
  }

  async fetchIssuesAndLinks() {

    this.isIssueAndLinkLoaded = false;
    const res = await this.factService.getFactIssuesAndLinks([this.nFSid]);
    if (res.length) {
      this.issueList = res[0] || []; // .filter(b => b.nFSid == a.nFSid)
      this.linkfiles = res[1] || []; // .filter(b => b.nFSid == a.nFSid)
      if (this.linkfiles.length) {
        this.linkfiles.forEach(element => {
          element.cPageRange = `${element?.jLinktype?.start}-${element?.jLinktype?.end}`
        });
      }
      console.log('link files', this.linkfiles);
    }
    this.isIssueAndLinkLoaded = true;
    this.cdr.detectChanges();
  }

  async initData() {
    this.timezoneList = await this.common.getCode(1);
    this.statusList = await this.common.getCode(3);
    this.filetypeList = await this.common.getCode(2);
    this.dateList = await this.common.getCode(16);
    this.bindCurrentTimezone();
    this.cdr.detectChanges();
  }

  bindCurrentTimezone() {
    const tmzone = Intl.DateTimeFormat().resolvedOptions().timeZone;
    const Tzone = this.timezoneList.find(m => m.jOther.includes(tmzone));
    this.usrtmzone = Tzone;
    if (Tzone) {
      // this.frm.patchValue({
      //   nTZid: Tzone.nValue
      // })
    }
  }

  onDateChange(e: string, column: string) {
    this.frm.get('jDate').patchValue({ [column]: e });
  }


  OnDetailFormEvent(e: toolEvents) {

    if (e.event == 'CLOSE') {
      this.FormType = null;
    } else if (e.event == 'REVIEW') {
      debugger;
      this.FormType = null;
      this.issueList = e.data.issueList;
      this.linkfiles = e.data.linkfiles || [];
      this.contactList = e.data.contactList || [];
      this.taskList = e.data.taskList || [];
      this.userList = e.data.userList || [];
      this.isEdited = true;
      this.jTexts = e.data.jTexts || [];
    } else if (e.event == 'DELETE-FACT') {
      this.onEvent.emit(e);
    } if (e?.event == 'VIEW-SOURCE') {

      this.curruntfact = e.data;
      // this.onEvent.emit(event);
    }
    this.cdr.detectChanges();
  }

  changeMode(mode) {
    this.isEdited = mode;
    this.cdr.detectChanges();
  }

  async reloadDetail() {
    debugger;
    const Factdata = await this.factService.getFactDetails([this.nFSid]);
    this.isEdited = false;
    this.isEdit = false;
    this.editUser = false;
    this.getOtherDetails();
    this.fillForm();
    this.jOText = Factdata[0].jOT || [];
    this.jTexts = Factdata[0].jTexts || [];

    this.cdr.detectChanges();
  }


  getdate(ind: number) {
    const date = new Date();
    date.setDate(date.getDate() - ind);
    return date;
  }


  async lastID(): Promise<string> {
    let lastId = null;
    const selectedIssues = this.issueList.map((a, index) => ({
      nIid: a.nIssueid || a.nIid,
      nImpactid: a.nImpactid,
      nRelid: a.nRelevanceid,
      dt: this.getdate(index),
      nSerial: a.nSerial
    }));
    let lastdata = await this.common.getcolorid(selectedIssues);
    if (lastdata.length) {
      lastId = lastdata[0]["nIid"];
    } else {
      lastId = selectedIssues[selectedIssues.length - 1]["nIid"]
    }
    return lastId ? lastId : null;
  }


  async updateFact() {
    debugger;
    const issues = this.issueList.map(a => ([a.nIssueid || a.nIid, a.nImpactid || 0, a.nRelevanceid || 0]));
    if (!issues.length) {
      this.tost.error('Please add atleast one issue');
      return;
    }
    const colorid = await this.lastID();
    const mdl = {
      ...this.frm.value,
      jIssue: this.convToStr(issues),
      jC: this.convToStr(this.contactList.map(a => a.nContactid)),
      jT: this.convToStr(this.taskList.map(a => a.nTaskid)),
      jU: this.convToStr(this.userList.filter(a => a.isSelected).map(a => a.nUserid)),
      jTexts: !this.jTexts.length ? '' : this.convToStr(this.jTexts),
      jL: this.convToStr(this.linkfiles.map(a => ([a.nFMLid || null, a.nBundledetailid || null, a.jLinktype || {}, a.highlights || [], a.texts || a.jOTexts || []]))),
      nColorid: colorid,
      bIsHighlighted: this.bIsHighlighted || false,
    };
    if (this.isFactUpdating) return;
    this.isFactUpdating = true;
    const res = await this.factService.updateFacts(mdl);

    if (res) {
      this.reloadDetail();
    }

    try {
      if (colorid) {
        const objIssue = this.issueList.find(a => a.nIid == colorid);
        if (objIssue) {
          this.onEvent.emit({ event: 'FACT-UPDATED', data: { nFSid: this.nFSid, color: objIssue.cColor, colorid: colorid } });
        }
      }
    } catch (error) {

    }

    this.isFactUpdating = false;
    this.cdr.detectChanges();
    if (res.msg == 1) {
      this.issaved = true;
      setTimeout(() => {
        this.issaved = false;
        this.cdr.detectChanges();
      }, 2000);
      this.isEdited = false;
      this.isEdit = false;
      this.editUser = false;
      this.getOtherDetails();
      this.tost.success(res.value);


    } else {
      this.tost.error(res.value);
    }

  }


  convToStr(val: any) {
    return JSON.stringify(val);
  }


  editHighlights() {
    this.onEvent.emit({ event: 'EDIT-HIGHLIGHT', data: { nFSid: this.factData.nFSid, index: this.nCurrent_annot } });
  }


  async deleteFact() {
    if (this.isDeleting) return;
    this.isDeleting = true;
    this.cdr.detectChanges();
    const res = await this.factService.deleteFact(this.nFSid);
    this.isDeleting = false;
    this.cdr.detectChanges();
    if (res && res.msg == 1) {
      this.onEvent.emit({ event: 'DELETE-FACT', data: { nFSid: this.factData.nFSid } });
    } else {
      this.tost.error(`Fact delete failed ${res.error}`);
    }


  }

  async addFactlink() {
    debugger
    if (this.dialogRef) return;
    this.dialogRef = this.dialog.open(FileexplorerComponent, {
      width: '90vw',
      height: '90vh',
      panelClass: ['rounded-xl', 'overflow-hidden'], // Rounded corners
      disableClose : true
      // data: {nCaseid:this.nCaseid}
    });
    this.dialogRef.componentInstance.nCaseid = this.nCaseid;
    this.dialogRef.componentInstance.isChooser = true;
    this.dialogRef.componentInstance.isLink = 'F';
    this.dialogRef.componentInstance.disabledFiles = this.linkfiles.map(a => a.nBundledetailid);
    this.dialogRef.afterClosed().subscribe(result => {
      try {
        const files = this.dialogRef.componentInstance.choosedFile;
        files.map(a => a.jOTexts = a.texts || []);
        files.map(e => { e.cPageRange = `${e?.jLinktype?.start}-${e?.jLinktype?.end}` || null })
        this.linkfiles = [...this.linkfiles, ...files];
        this.isEdited = true;
      } catch (error) {
      }
      this.dialogRef = null;
      this.cdr.detectChanges();
    });
  }


  launchInPreview() {
    this.previewMode = true;
    this.cdr.detectChanges();
  }



  OnEventOfPreview(e) {
    if (e.event == 'CLOSE') {
      this.previewMode = false;
      this.cdr.detectChanges();
    }
  }


  selctfactlink(x) {
    // console.log(x);
    // this.linkfiles.forEach((item) => {
    //   item.isSelected = false;
    // });
    // x.isSelected = true;
    this.curruntfact = x;

    // this.onEvent.emit({ event: 'OPEN-FACT-FROM-FACT-SHEET', data: x });
  }

  deselect() {
    this.linkfiles.forEach((item) => {
      item.isSelected = false;
    });
  }

  expandView() {
    this.onEvent.emit({ event: 'EXPAND-PREVIEW', data: this.quickPreviewFiles });
  }


  async confirmConvertToFile() {

    this.factData;
    this.docInfo;
    const linkType = this.factData.jLinktype;
    delete linkType.pages;
    linkType.type = 'F';

    const mdl = {
      nFSid: this.factData.nFSid,
      jLinktype: JSON.stringify(linkType)
    }
    const res = await this.factService.convertFact(mdl);
    if (res.msg == 1) {

      this.onEvent.emit({ event: 'FACT-CONVERT-HIGHLIGHT-TO-FILE', data: { nFSid: this.factData.nFSid } });
      this.reloadFactSheet();
      this.tost.success(res.value);
    } else {
      this.tost.error('Failed to convert fact');
    }
  }
  async convertToPageLevel(data) {
    this.factData;
    this.docInfo;
    const linkType = this.factData.jLinktype;
    delete linkType.pages;
    linkType.type = 'P';
    linkType.start = data.start;
    linkType.end = data.end;

    const mdl = {
      nFSid: this.factData.nFSid,
      jLinktype: JSON.stringify(linkType)
    }
    const res = await this.factService.convertFact(mdl);
    if (res.msg == 1) {

      this.onEvent.emit({ event: 'FACT-CONVERT-HIGHLIGHT-TO-FILE', data: { nFSid: this.factData.nFSid } });
      this.reloadFactSheet();
      this.tost.success(res.value);
    } else {
      this.tost.error('Failed to convert fact');
    }
  }

  confirmConvertToPageLevel() {

    this.onEvent.emit({ event: 'FACT-CONVERT-HIGHLIGHT-TO-PAGERANGE', data: { nFSid: this.factData.nFSid } });
  }

  updatejtext(ev) {
    this.isEdited = true;
  }

  OnFilesEvnets(event) {
    if (event?.event == 'VIEW-SOURCE') {
      this.onEvent.emit(event);
    }
  }
  OnQuickPreviewEvent(e) {
    debugger;
    this.onEvent.emit({ event: 'OPEN-FACT-FROM-FACT-SHEET', data: e.data });
  }
}
