import { Injectable } from '@angular/core';
import { presentChangeTab, presentCompare, presentCompareData, presentPosition } from '../../interfaces/present-action.interface';
import { SocketService } from '../../../core/services/socket/socket.service';

@Injectable({
  providedIn: 'root'
})
export class PresentActionsService {

  constructor(private readonly socket: SocketService) {


  }

  emitPositionData(data: presentPosition) {
    this.socket.sendMessage('present-position', data);
  }


  emitCurrentTabData(data: presentChangeTab) {
    this.socket.sendMessage('present-change-tab', data);
  }


  emitCompare(data: presentCompare) {
    this.socket.sendMessage('present-compare', data);
  }

  emitCompareData(data: presentCompareData) {
    this.socket.sendMessage('present-compare-data', data);
  }
}
